import {test,expect} from '@playwright/test';
// UI fixtures only. Production evidence is generated by the offline analysis;
// numerical correctness and null-model properties are tested in Python.
const areas=Array.from({length:40},(_,i)=>({id:String(i),name:'Test area '+i,district:i%10+1,areaKm2:1,centroid:[i%8*100,Math.floor(i/8)*100]}));
const variable=(index:number)=>({id:String(index),index,seriesId:String(index),dataset:'test-'+index,datasetTitle:index?'Income fixture':'Trees fixture',category:index?'Society':'Nature',field:index?'Income':'Trees / km²',stratum:{},areaLevel:'neighbourhood',year:2023,dateBasis:'record',aggregation:'Median of test observations',values:areas.map((_,i)=>(i+1)*(index+1)),counts:areas.map(()=>1),testable:true,eligibilityReason:'Spatial inference eligible',limitation:null,summary:{median:20,min:1,max:40},n:40,resourceName:'test.csv',resourceUrl:'https://example.com/test.csv',datasetUrl:'https://example.com',license:'Test fixture',sha256:'fixture',sourceRows:40,unmappedRows:0,retrievedAt:'2026-11-07',duplicateResources:[]});
const manifest={version:1,generatedAt:'2026-11-07T00:00:00Z',seed:20261107,permutations:9999,minAreas:30,fdrMethod:'BY',counts:{datasets:2,usableVariables:2,comparisons:1,supported:0,resources:2,editions:2,fieldsScreened:2,spatialTests:1,derivedVariables:2,duplicateVariables:0,sparseStrataExcluded:0,failedEditions:0},areas:{neighbourhood:areas},periods:{'2023-neighbourhood':{year:2023,areaLevel:'neighbourhood',variables:2,comparisons:1,spatialTests:1,controls:'District fixed effects',shards:[0],supported:0}},datasetCoverage:[],sources:[]};
const pair=[0,1,40,1,1,.4,.01,.1];
async function evidence(page:import('@playwright/test').Page){await page.route('**/api/analytics/**',async route=>{const url=route.request().url();const body=url.endsWith('/manifest.json')?manifest:url.endsWith('/top-associations.json')?{'2023-neighbourhood':[pair]}:url.endsWith('/diagnostics.json')?{}:url.includes('/variables/')?[variable(0),variable(1)]:[pair];await route.fulfill({json:body});});}
test('fourth navigation item opens analytics, exposes evidence and exports area values',async({page})=>{
 await evidence(page);await page.goto('/');await page.getByRole('button',{name:'Analytics',exact:true}).click();
 await expect(page.getByRole('main',{name:'Analytics dashboard'})).toBeVisible();
 await expect(page).toHaveURL(/view=analytics/);
 await expect(page.locator('.analysis-metrics')).toContainText('0.1');
 await expect(page.locator('.analysis-interpretation')).toContainText('exploratory');
 const download=page.waitForEvent('download');await page.getByRole('button',{name:'Export comparison'}).click();expect((await download).suggestedFilename()).toContain('2023-neighbourhood.csv');
 await page.getByRole('tab',{name:'Coverage & methods'}).click();await expect(page.getByText('Limits that change interpretation')).toBeVisible();
 await page.getByRole('button',{name:'Explore the map',exact:true}).click();await expect(page.getByRole('main',{name:'Map explorer'})).toBeVisible();
});
test('analytics loads from a shared URL and keeps all four navigation items on mobile',async({page})=>{
 await evidence(page);await page.setViewportSize({width:390,height:844});await page.goto('/?view=analytics');
 await expect(page.getByLabel('Measure X',{exact:true})).toBeVisible();
 for(const name of ['Explore the map','Dataset catalog','Data & sources','Analytics'])await expect(page.getByRole('button',{name,exact:true})).toBeVisible();
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.getByRole('tab',{name:'Coverage & methods'}).click();await expect(page.getByRole('link',{name:/Every source field/})).toBeVisible();
});
test('analytics failure is explicit and retry recovers',async({page})=>{
 await page.route('**/api/analytics/**',r=>r.fulfill({status:503,json:{detail:'Offline'}}));await page.goto('/?view=analytics');await expect(page.getByRole('alert')).toContainText('could not load');
 await page.unroute('**/api/analytics/**');await evidence(page);await page.getByRole('button',{name:'Retry analytics'}).click();await expect(page.getByLabel('Measure X',{exact:true})).toBeVisible();
});
